import { normalizeDueRange, matchesDueRange } from './due-date.js';
import { matchesSearch } from './search.js';

const app = document.querySelector('#app');

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text) node.textContent = text;
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  return node;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function showError(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p', '', { role: 'alert' });
    app.append(alert);
  }
  alert.textContent = message;
}

function searchForm(id, label, buttonLabel, onSearch) {
  const form = element('form', '', { class: 'search-form' });
  const input = element('input', '', { id, type: 'text' });
  form.append(element('label', label, { for: id }), input,
    element('button', buttonLabel, { type: 'submit' }));
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const query = input.value.trim();
    input.value = query;
    onSearch(query);
  });
  return form;
}

function projectRow(project, onArchiveChange) {
  const row = element('li', '', { 'data-testid': 'project-row' });
  const open = element('button', 'Open project', { type: 'button' });
  open.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project', { type: 'button' });
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      app.querySelector('[role="alert"]')?.remove();
      onArchiveChange();
    } catch (error) {
      showError(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  const details = element('div', '', { class: 'project-details' });
  details.append(element('span', project.name), element('span',
    `${project.completedCount}/${project.totalCount} completed`, { 'data-testid': 'project-summary' }));
  const actions = element('div', '', { class: 'project-actions' });
  actions.append(open, archive);
  row.append(details, actions);
  return row;
}

async function showProjects() {
  app.replaceChildren(element('h1', 'Workboard'));
  let projects = [];
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', '', { id: 'project-name', name: 'name', type: 'text' });
  const create = element('button', 'Create project', { type: 'submit' });
  form.append(label, input, create);
  const list = element('ul', '', { 'aria-label': 'Projects', class: 'projects' });
  const filter = element('select', '', { id: 'project-filter' });
  for (const option of ['Active', 'Archived']) {
    filter.append(element('option', option, { value: option }));
  }
  const filters = element('div', '', { class: 'project-filters' });
  filters.append(element('label', 'Project filter', { for: 'project-filter' }), filter);
  let searchQuery = '';
  const search = searchForm('project-search', 'Project search', 'Search projects', (query) => {
    searchQuery = query;
    renderProjects();
  });
  function renderProjects() {
    const visible = projects.filter((project) => project.archived === (filter.value === 'Archived')
      && matchesSearch(project.name, searchQuery));
    list.replaceChildren(...visible.map((project) => projectRow(project, renderProjects)));
  }
  filter.addEventListener('change', renderProjects);
  app.append(form, filters, search, list);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (create.disabled) return;
    const name = input.value.trim();
    if (!name) {
      showError('Project name is required');
      return;
    }
    create.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      projects.push(project);
      renderProjects();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      create.disabled = false;
    }
  });
  // Load the persisted list before allowing writes so initial rows stay in order.
  create.disabled = true;
  try {
    projects = await request('/api/projects');
    renderProjects();
    create.disabled = false;
  } finally {
    app.setAttribute('aria-busy', 'false');
  }
}

async function showProject(id) {
  app.replaceChildren();
  const back = element('button', 'Projects', { type: 'button' });
  back.addEventListener('click', () => { window.location.href = '/'; });
  app.append(back);
  try {
    const project = await request(`/api/projects/${id}`);
    const heading = element('h1', project.name);
    app.append(heading);
    document.title = `${project.name} · Workboard`;
    if (project.archived) app.append(element('p', 'Archived project'));
    showProjectRename(project, heading);
    showProjectDefaultPriority(project);
    await showTasks(id, project.archived);
  } finally {
    app.setAttribute('aria-busy', 'false');
  }
}

function showProjectRename(project, heading) {
  const form = element('form', '', { class: 'project-rename' });
  const input = element('input', '', { id: 'new-project-name', name: 'name', type: 'text' });
  const rename = element('button', 'Rename project', { type: 'submit' });
  input.value = project.name;
  input.disabled = project.archived;
  rename.disabled = project.archived;
  form.append(element('label', 'New project name', { for: 'new-project-name' }), input, rename);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (rename.disabled) return;
    const name = input.value.trim();
    if (!name) return showError('Project name is required');
    rename.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      project.name = saved.name;
      heading.textContent = project.name;
      document.title = `${project.name} · Workboard`;
      input.value = project.name;
      app.querySelector('[role="alert"]')?.remove();
    } catch (error) {
      showError(error.message);
    } finally {
      rename.disabled = project.archived;
    }
  });
  app.append(form);
}

function showProjectDefaultPriority(project) {
  const control = element('div', '', { class: 'project-default-priority' });
  const select = element('select', '', { id: 'default-task-priority' });
  for (const priority of ['Low', 'Normal', 'High']) {
    select.append(element('option', priority, { value: priority }));
  }
  select.value = project.defaultPriority;
  select.disabled = project.archived;
  select.addEventListener('change', async () => {
    if (select.disabled) return;
    select.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ defaultPriority: select.value }),
      });
      project.defaultPriority = saved.defaultPriority;
      app.querySelector('[role="alert"]')?.remove();
    } catch (error) {
      showError(error.message);
    } finally {
      select.value = project.defaultPriority;
      select.disabled = project.archived;
    }
  });
  control.append(element('label', 'Default task priority', { for: 'default-task-priority' }), select);
  app.append(control);
}

function taskRenameForm(task, path, archived, onRename) {
  const form = element('form', '', { class: 'task-rename' });
  const inputId = `new-task-title-${task.id}`;
  const input = element('input', '', { id: inputId, name: 'title', type: 'text' });
  const rename = element('button', 'Rename task', { type: 'submit' });
  input.value = task.title;
  input.disabled = archived;
  rename.disabled = archived;
  form.append(element('label', 'New task title', { for: inputId }), input, rename);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (rename.disabled) return;
    const title = input.value.trim();
    if (!title) return showError('Task title is required');
    rename.disabled = true;
    try {
      const saved = await request(`${path}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      task.title = saved.title;
      app.querySelector('[role="alert"]')?.remove();
      onRename();
    } catch (error) {
      showError(error.message);
    } finally {
      rename.disabled = archived;
    }
  });
  return form;
}

function taskPriorityControl(task, path, archived, onPriorityChange) {
  const control = element('div', '', { class: 'task-priority' });
  const inputId = `task-priority-${task.id}`;
  const select = element('select', '', { id: inputId });
  for (const priority of ['Low', 'Normal', 'High']) {
    select.append(element('option', priority, { value: priority }));
  }
  select.value = task.priority;
  select.disabled = archived;
  select.addEventListener('change', async () => {
    if (select.disabled) return;
    select.disabled = true;
    try {
      const saved = await request(`${path}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priority: select.value }),
      });
      // This write only changes priority; other controls may have saved meanwhile.
      task.priority = saved.priority;
      app.querySelector('[role="alert"]')?.remove();
      onPriorityChange();
    } catch (error) {
      showError(error.message);
    } finally {
      select.value = task.priority;
      select.disabled = archived;
    }
  });
  control.append(element('label', 'Task priority', { for: inputId }), select);
  return control;
}

function taskDueDateForm(task, path, archived, onDueDateChange) {
  const form = element('form', '', { class: 'task-due-date' });
  const inputId = `task-due-date-${task.id}`;
  const input = element('input', '', { id: inputId, name: 'dueDate', type: 'text', placeholder: 'YYYY-MM-DD' });
  const save = element('button', 'Save due date', { type: 'submit' });
  input.value = task.dueDate ?? '';
  input.disabled = archived;
  save.disabled = archived;
  form.append(element('label', 'Task due date', { for: inputId }), input, save);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (save.disabled) return;
    save.disabled = true;
    try {
      const saved = await request(`${path}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dueDate: input.value }),
      });
      // Preserve any concurrent changes saved by the other task controls.
      task.dueDate = saved.dueDate;
      input.value = task.dueDate;
      app.querySelector('[role="alert"]')?.remove();
      onDueDateChange();
    } catch (error) {
      showError(error.message);
    } finally {
      save.disabled = archived;
    }
  });
  return form;
}

function taskMoveForm(task, path, archived, destinations, onMove) {
  const form = element('form', '', { class: 'task-move' });
  const inputId = `destination-project-${task.id}`;
  const select = element('select', '', { id: inputId });
  for (const project of destinations) {
    select.append(element('option', project.name, { value: String(project.id) }));
  }
  const move = element('button', 'Move task', { type: 'submit' });
  const disabled = archived || destinations.length === 0;
  select.disabled = disabled;
  move.disabled = disabled;
  form.append(element('label', 'Destination project', { for: inputId }), select, move);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (move.disabled) return;
    select.disabled = true;
    move.disabled = true;
    try {
      await request(`${path}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ destinationProjectId: Number(select.value) }),
      });
      app.querySelector('[role="alert"]')?.remove();
      onMove();
    } catch (error) {
      showError(error.message);
    } finally {
      select.disabled = disabled;
      move.disabled = disabled;
    }
  });
  return form;
}

async function showTasks(projectId, archived) {
  const path = `/api/projects/${projectId}/tasks`;
  let tasks = [];
  let destinations = [];
  const form = element('form');
  const input = element('input', '', { id: 'task-title', name: 'title', type: 'text' });
  const create = element('button', 'Create task', { type: 'submit' });
  create.disabled = true;
  form.append(element('label', 'Task title', { for: 'task-title' }), input, create);
  const filter = element('select', '', { id: 'task-filter' });
  for (const option of ['All', 'Open', 'Completed']) {
    filter.append(element('option', option, { value: option }));
  }
  const priorityFilter = element('select', '', { id: 'priority-filter' });
  for (const option of ['All', 'Low', 'Normal', 'High']) {
    priorityFilter.append(element('option', option, { value: option }));
  }
  const filters = element('div', '', { class: 'task-filters' });
  filters.append(element('label', 'Task filter', { for: 'task-filter' }), filter,
    element('label', 'Priority filter', { for: 'priority-filter' }), priorityFilter);
  let dueRange = { from: '', through: '' };
  const dueRangeForm = element('form', '', { class: 'due-range' });
  const dueFrom = element('input', '', { id: 'due-from', type: 'text', placeholder: 'YYYY-MM-DD' });
  const dueThrough = element('input', '', { id: 'due-through', type: 'text', placeholder: 'YYYY-MM-DD' });
  dueRangeForm.append(element('label', 'Due from', { for: 'due-from' }), dueFrom,
    element('label', 'Due through', { for: 'due-through' }), dueThrough,
    element('button', 'Apply due range', { type: 'submit' }));
  dueRangeForm.addEventListener('submit', (event) => {
    event.preventDefault();
    const range = normalizeDueRange(dueFrom.value, dueThrough.value);
    if (range.error) return showError(range.error);
    dueRange = range;
    dueFrom.value = range.from;
    dueThrough.value = range.through;
    app.querySelector('[role="alert"]')?.remove();
    renderTasks();
  });
  const list = element('ul', '', { 'aria-label': 'Tasks', class: 'tasks' });
  let searchQuery = '';
  const search = searchForm('task-search', 'Task search', 'Search tasks', (query) => {
    searchQuery = query;
    renderTasks();
  });
  app.append(form, filters, dueRangeForm, search, list);

  function renderTasks() {
    const visible = tasks.filter((task) =>
      (filter.value === 'All' || (filter.value === 'Completed' ? task.completed : !task.completed))
      && (priorityFilter.value === 'All' || task.priority === priorityFilter.value)
      && matchesDueRange(task.dueDate, dueRange)
      && matchesSearch(task.title, searchQuery));
    list.replaceChildren(...visible.map((task) => {
      const row = element('li', '', { 'data-testid': 'task-row' });
      const checkbox = element('input', '', {
        type: 'checkbox', 'aria-label': `Complete ${task.title}`,
      });
      checkbox.checked = task.completed;
      checkbox.disabled = archived;
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        try {
          const saved = await request(`${path}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = saved.completed;
          app.querySelector('[role="alert"]')?.remove();
          renderTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(error.message);
        } finally {
          checkbox.disabled = archived;
        }
      });
      const details = element('div', '', { class: 'task-details' });
      details.append(element('span', task.title), taskRenameForm(task, path, archived, renderTasks),
        taskPriorityControl(task, path, archived, renderTasks), taskDueDateForm(task, path, archived, renderTasks),
        taskMoveForm(task, path, archived, destinations, () => {
          tasks = tasks.filter((remaining) => remaining.id !== task.id);
          renderTasks();
        }));
      row.append(checkbox, details);
      return row;
    }));
  }

  filter.addEventListener('change', renderTasks);
  priorityFilter.addEventListener('change', renderTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (create.disabled) return;
    const title = input.value.trim();
    if (!title) return showError('Task title is required');
    create.disabled = true;
    try {
      const task = await request(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      tasks.push(task);
      renderTasks();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      create.disabled = archived;
    }
  });
  const [savedTasks, projects] = await Promise.all([request(path), request('/api/projects')]);
  tasks = savedTasks;
  destinations = projects.filter((project) => !project.archived && project.id !== Number(projectId));
  renderTasks();
  create.disabled = archived;
}

const projectRoute = window.location.pathname.match(/^\/projects\/(\d+)$/);
try {
  if (projectRoute) await showProject(projectRoute[1]);
  else await showProjects();
} catch (error) {
  showError(error.message);
}

import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { normalizeDueDate } from './due-date.js';

const databasePath = process.env.DB_PATH || './data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK (length(trim(name)) > 0),
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
    default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK (length(trim(title)) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High')),
    due_date TEXT NOT NULL DEFAULT '',
    position INTEGER NOT NULL DEFAULT 0
  );
  CREATE INDEX IF NOT EXISTS tasks_by_project ON tasks(project_id, id);
`);
// Existing projects stay active when upgrading a projects/tasks database.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
// Project defaults apply only to future tasks; existing task priorities stay intact.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
// Backfill existing tasks without changing their IDs, order, or completion.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
// Existing tasks have no due date; this migration preserves every other field.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
  database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
// Preserve legacy creation order while allowing moved tasks to append independently of IDs.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
  database.exec(`BEGIN;
    ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0;
    UPDATE tasks SET position = id;
    COMMIT;`);
}
database.exec('CREATE INDEX IF NOT EXISTS tasks_by_project_position ON tasks(project_id, position, id)');
// Remember positions even while tasks are away. Backfill the current order on
// upgrade; prior visits cannot be reconstructed from the previous schema.
database.exec(`
  BEGIN;
  CREATE TABLE IF NOT EXISTS task_project_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id),
    project_id INTEGER NOT NULL REFERENCES projects(id),
    position INTEGER NOT NULL,
    PRIMARY KEY (task_id, project_id)
  );
  CREATE INDEX IF NOT EXISTS remembered_positions_by_project
    ON task_project_positions(project_id, position);
  INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
    SELECT id, project_id, position FROM tasks;
  COMMIT;
`);
const projectSelection = `
  SELECT projects.id, projects.name, projects.archived, projects.default_priority AS defaultPriority,
    COUNT(tasks.id) AS totalCount, COALESCE(SUM(tasks.completed), 0) AS completedCount
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
`;
const listProjects = database.prepare(`${projectSelection} GROUP BY projects.id ORDER BY projects.id`);
const findProject = database.prepare(`${projectSelection} WHERE projects.id = ? GROUP BY projects.id`);
const updateProjectArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateProjectDefaultPriority = database.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? ORDER BY position, id');
const findTask = database.prepare('SELECT id, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = database.prepare(`
  INSERT INTO tasks (project_id, title, priority, position)
  SELECT id, ?, default_priority,
    (SELECT COALESCE(MAX(position), 0) + 1 FROM task_project_positions WHERE project_id = projects.id)
  FROM projects WHERE id = ?
`);
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const updateTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const rememberCurrentPosition = database.prepare(`
  INSERT INTO task_project_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks WHERE id = ?
`);
const rememberDestinationPosition = database.prepare(`
  INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
  SELECT ?, ?, COALESCE(MAX(position), 0) + 1
  FROM task_project_positions WHERE project_id = ?
`);
const updateTaskProject = database.prepare(`
  UPDATE tasks SET project_id = ?,
    position = (SELECT position FROM task_project_positions WHERE task_id = ? AND project_id = ?)
  WHERE project_id = ? AND id = ?
`);

function inTransaction(write) {
  database.exec('BEGIN');
  try {
    const result = write();
    database.exec('COMMIT');
    return result;
  } catch (error) {
    database.exec('ROLLBACK');
    throw error;
  }
}

function createTask(title, projectId) {
  return inTransaction(() => {
    const result = insertTask.run(title, projectId);
    rememberCurrentPosition.run(result.lastInsertRowid);
    return result.lastInsertRowid;
  });
}

function moveTask(taskId, sourceId, destinationId) {
  inTransaction(() => {
    rememberDestinationPosition.run(taskId, destinationId, destinationId);
    updateTaskProject.run(destinationId, taskId, destinationId, sourceId, taskId);
  });
}

function projectData(project) {
  return { ...project, archived: Boolean(project.archived) };
}

function taskData(task) {
  return { ...task, completed: Boolean(task.completed) };
}

const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/due-date.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./due-date.js', import.meta.url))]],
  ['/search.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./search.js', import.meta.url))]],
  ['/styles.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/styles.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 16_384) throw new Error('Request body is too large');
    chunks.push(chunk);
  }
  return JSON.parse(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const pathname = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && pathname === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (pathname === '/api/projects' && request.method === 'GET') {
      return json(response, 200, listProjects.all().map(projectData));
    }
    if (pathname === '/api/projects' && request.method === 'POST') {
      let body;
      try {
        body = await readJson(request);
      } catch {
        return json(response, 400, { error: 'Invalid JSON request' });
      }
      const name = typeof body?.name === 'string' ? body.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, projectData(findProject.get(result.lastInsertRowid)));
    }
    const projectRoute = pathname.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectRoute) {
      const project = findProject.get(projectRoute[1]);
      return project ? json(response, 200, projectData(project)) : json(response, 404, { error: 'Project not found' });
    }
    if (request.method === 'PATCH' && projectRoute) {
      const projectId = projectRoute[1];
      if (!findProject.get(projectId)) return json(response, 404, { error: 'Project not found' });
      let body;
      try {
        body = await readJson(request);
      } catch {
        return json(response, 400, { error: 'Invalid JSON request' });
      }
      if (body && Object.hasOwn(body, 'defaultPriority')) {
        if (Object.hasOwn(body, 'name') || Object.hasOwn(body, 'archived')) {
          return json(response, 400, { error: 'Default priority, rename, and archive must be separate requests' });
        }
        if (findProject.get(projectId).archived) {
          return json(response, 409, { error: 'Archived project cannot be changed' });
        }
        if (!['Low', 'Normal', 'High'].includes(body.defaultPriority)) {
          return json(response, 400, { error: 'Default task priority must be Low, Normal, or High' });
        }
        updateProjectDefaultPriority.run(body.defaultPriority, projectId);
        return json(response, 200, projectData(findProject.get(projectId)));
      }
      if (body && Object.hasOwn(body, 'name')) {
        if (Object.hasOwn(body, 'archived')) {
          return json(response, 400, { error: 'Rename and archive must be separate requests' });
        }
        // Check after reading input so a concurrent archive cannot allow a rename.
        if (findProject.get(projectId).archived) {
          return json(response, 409, { error: 'Archived project cannot be changed' });
        }
        const name = typeof body.name === 'string' ? body.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, projectId);
        return json(response, 200, projectData(findProject.get(projectId)));
      }
      if (typeof body?.archived !== 'boolean') {
        return json(response, 400, { error: 'Project archive state must be a boolean' });
      }
      updateProjectArchive.run(Number(body.archived), projectId);
      return json(response, 200, projectData(findProject.get(projectId)));
    }
    const tasksRoute = pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksRoute) {
      const [, projectId, taskId] = tasksRoute;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (!taskId && request.method === 'GET') {
        return json(response, 200, listTasks.all(projectId).map(taskData));
      }
      if ((!taskId && request.method === 'POST') || (taskId && request.method === 'PATCH')) {
        if (project.archived) return json(response, 409, { error: 'Archived project cannot be changed' });
        if (taskId && !findTask.get(projectId, taskId)) {
          return json(response, 404, { error: 'Task not found' });
        }
        let body;
        try {
          body = await readJson(request);
        } catch {
          return json(response, 400, { error: 'Invalid JSON request' });
        }
        // Recheck after reading the body: an archive request may have completed
        // while this request was awaiting input. No awaits occur before the write.
        if (findProject.get(projectId).archived) {
          return json(response, 409, { error: 'Archived project cannot be changed' });
        }
        if (taskId && !findTask.get(projectId, taskId)) {
          return json(response, 404, { error: 'Task not found' });
        }
        if (!taskId) {
          const title = typeof body?.title === 'string' ? body.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          const createdId = createTask(title, projectId);
          return json(response, 201, taskData(findTask.get(projectId, createdId)));
        }
        if (body && Object.hasOwn(body, 'destinationProjectId')) {
          if (['dueDate', 'priority', 'title', 'completed'].some((field) => Object.hasOwn(body, field))) {
            return json(response, 400, { error: 'Move and other task edits must be separate requests' });
          }
          const destinationId = body.destinationProjectId;
          if (!Number.isSafeInteger(destinationId) || destinationId <= 0 || destinationId === Number(projectId)) {
            return json(response, 400, { error: 'Choose another active destination project' });
          }
          const destination = findProject.get(destinationId);
          if (!destination) return json(response, 404, { error: 'Destination project not found' });
          if (destination.archived) return json(response, 409, { error: 'Archived project cannot receive tasks' });
          // Save a first-visit position or reuse the remembered one atomically.
          moveTask(taskId, projectId, destinationId);
          return json(response, 200, taskData(findTask.get(destinationId, taskId)));
        }
        if (body && Object.hasOwn(body, 'dueDate')) {
          if (['priority', 'title', 'completed'].some((field) => Object.hasOwn(body, field))) {
            return json(response, 400, { error: 'Due date and other task edits must be separate requests' });
          }
          const dueDate = normalizeDueDate(body.dueDate);
          if (dueDate === null) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          updateTaskDueDate.run(dueDate, projectId, taskId);
          return json(response, 200, taskData(findTask.get(projectId, taskId)));
        }
        if (body && Object.hasOwn(body, 'priority')) {
          if (Object.hasOwn(body, 'title') || Object.hasOwn(body, 'completed')) {
            return json(response, 400, { error: 'Priority, rename, and completion must be separate requests' });
          }
          if (!['Low', 'Normal', 'High'].includes(body.priority)) {
            return json(response, 400, { error: 'Task priority must be Low, Normal, or High' });
          }
          updateTaskPriority.run(body.priority, projectId, taskId);
          return json(response, 200, taskData(findTask.get(projectId, taskId)));
        }
        if (body && Object.hasOwn(body, 'title')) {
          if (Object.hasOwn(body, 'completed')) {
            return json(response, 400, { error: 'Rename and completion must be separate requests' });
          }
          const title = typeof body.title === 'string' ? body.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return json(response, 200, taskData(findTask.get(projectId, taskId)));
        }
        if (typeof body?.completed !== 'boolean') {
          return json(response, 400, { error: 'Task completion must be a boolean' });
        }
        updateTask.run(Number(body.completed), projectId, taskId);
        return json(response, 200, taskData(findTask.get(projectId, taskId)));
      }
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(pathname) ? '/' : pathname);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    if (!response.headersSent) json(response, 500, { error: 'Unable to complete request' });
    else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.once(signal, () => {
    server.close(() => {
      database.close();
      process.exit(0);
    });
    server.closeIdleConnections();
  });
}

import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { test } from 'node:test';
import { DatabaseSync } from 'node:sqlite';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    cwd: new URL('../', import.meta.url),
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', (chunk) => { errors += chunk; });
  const url = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      child.kill();
      reject(new Error(`Server startup timed out: ${errors}`));
    }, 5000);
    child.once('error', (error) => { clearTimeout(timeout); reject(error); });
    child.once('exit', (code) => {
      clearTimeout(timeout);
      reject(new Error(`Server exited with ${code}: ${errors}`));
    });
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) {
        clearTimeout(timeout);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    url,
    async stop() {
      if (child.exitCode !== null) return;
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('task rename preserves ownership, order, completion, and counts through restarts and restore', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-task-rename-test-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let server;
  try {
    server = await startServer(databasePath);
    const api = async (path, method = 'GET', body) => {
      const response = await fetch(`${server.url}${path}`, {
        method,
        ...(body === undefined ? {} : {
          headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
        }),
      });
      return { status: response.status, body: await response.json() };
    };
    const project = (await api('/api/projects', 'POST', { name: 'First' })).body;
    const other = (await api('/api/projects', 'POST', { name: 'Other' })).body;
    const projectPath = `/api/projects/${project.id}`;
    const path = `${projectPath}/tasks`;
    const first = (await api(path, 'POST', { title: 'Original' })).body;
    const second = (await api(path, 'POST', { title: 'Second' })).body;
    const completed = (await api(`${path}/${first.id}`, 'PATCH', { completed: true })).body;
    const summary = { ...project, completedCount: 1, totalCount: 2 };
    for (const title of ['', ' \t\n ', null, 42]) {
      assert.deepEqual(await api(`${path}/${first.id}`, 'PATCH', { title }), {
        status: 400, body: { error: 'Task title is required' },
      });
    }
    assert.equal((await api(`${path}/${first.id}`, 'PATCH', { title: 'Combined', completed: false })).status, 400);
    assert.equal((await api(`/api/projects/${other.id}/tasks/${first.id}`, 'PATCH', { title: 'Wrong owner' })).status, 404);
    assert.equal((await api(`${path}/999999`, 'PATCH', { title: 'Missing' })).status, 404);
    assert.deepEqual((await api(path)).body, [completed, second]);
    const renamed = { ...completed, title: '<b>Renamed task</b>' };
    assert.deepEqual(await api(`${path}/${first.id}`, 'PATCH', { title: '  <b>Renamed task</b> \n' }), {
      status: 200, body: renamed,
    });
    assert.deepEqual((await api(path)).body, [renamed, second]);
    assert.deepEqual((await api(projectPath)).body, summary);
    assert.deepEqual((await api(`/api/projects/${other.id}/tasks`)).body, []);
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual((await api(path)).body, [renamed, second]);
    assert.deepEqual((await api(projectPath)).body, summary);
    await api(projectPath, 'PATCH', { archived: true });
    assert.deepEqual(await api(`${path}/${first.id}`, 'PATCH', { title: 'Blocked' }), {
      status: 409, body: { error: 'Archived project cannot be changed' },
    });
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual((await api(path)).body, [renamed, second]);
    await api(projectPath, 'PATCH', { archived: false });
    const restored = { ...renamed, title: 'After restoration' };
    assert.deepEqual(await api(`${path}/${first.id}`, 'PATCH', { title: restored.title }), {
      status: 200, body: restored,
    });
    const renamedOpen = { ...second, title: 'Renamed open task' };
    await api(`${path}/${second.id}`, 'PATCH', { title: renamedOpen.title });
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual((await api(path)).body, [restored, renamedOpen]);
    assert.deepEqual((await api('/api/projects')).body, [summary, other]);
  } finally {
    await server?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('projects validate, keep creation order, and persist names and IDs after restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const databasePath = join(directory, 'nested', 'projects.sqlite');
  let server;
  try {
    server = await startServer(databasePath);
    const api = async (path, options) => {
      const response = await fetch(`${server.url}${path}`, options);
      return { status: response.status, body: await response.json() };
    };
    const create = (name) => api('/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });

    assert.deepEqual(await api('/health'), { status: 200, body: { status: 'ok' } });
    assert.deepEqual((await api('/api/projects')).body, []);
    for (const name of ['', ' \t\n ', null, 42]) {
      assert.deepEqual(await create(name), { status: 400, body: { error: 'Project name is required' } });
    }
    assert.deepEqual((await api('/api/projects')).body, []);
    const first = await create('  First project \n');
    const second = await create('<script>literal text</script>');
    assert.equal(first.status, 201);
    assert.equal(second.status, 201);
    assert.equal(first.body.name, 'First project');
    assert.ok(Number.isInteger(first.body.id));
    assert.ok(second.body.id > first.body.id);
    const projects = [first.body, second.body];
    assert.deepEqual((await api('/api/projects')).body, projects);
    assert.deepEqual(await api(`/api/projects/${first.body.id}`), { status: 200, body: first.body });
    assert.equal((await api('/api/projects/999999')).status, 404);
    assert.equal((await api('/missing')).status, 404);
    const invalid = await api('/api/projects', { method: 'POST', body: '{' });
    assert.equal(invalid.status, 400);
    assert.deepEqual((await api('/api/projects')).body, projects);
    for (const path of ['/', `/projects/${first.body.id}`]) {
      const response = await fetch(`${server.url}${path}`);
      assert.equal(response.status, 200);
      assert.match(response.headers.get('content-type'), /text\/html/);
      assert.match(await response.text(), /<title>Workboard<\/title>/);
    }
    for (const path of ['/app.js', '/styles.css']) {
      assert.equal((await fetch(`${server.url}${path}`)).status, 200);
    }
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual((await api('/api/projects')).body, projects);
    assert.deepEqual((await api(`/api/projects/${first.body.id}`)).body, first.body);
    const third = await create('Third');
    assert.ok(third.body.id > second.body.id);
    assert.deepEqual((await api('/api/projects')).body, [...projects, third.body]);
  } finally {
    await server?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('tasks validate, belong to one project, and persist completion across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-test-'));
  const databasePath = join(directory, 'workboard.sqlite');
  // Start from the original projects-only schema to verify existing data survives.
  const legacy = new DatabaseSync(databasePath);
  legacy.exec(`
    CREATE TABLE projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    );
    INSERT INTO projects (name) VALUES ('Existing project');
  `);
  legacy.close();
  let server;
  try {
    server = await startServer(databasePath);
    const api = async (path, method = 'GET', body) => {
      const response = await fetch(`${server.url}${path}`, {
        method,
        ...(body === undefined ? {} : {
          headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
        }),
      });
      return { status: response.status, body: await response.json() };
    };
    assert.deepEqual((await api('/api/projects')).body, [{ id: 1, name: 'Existing project', archived: false, defaultPriority: 'Normal', totalCount: 0, completedCount: 0 }]);
    const other = (await api('/api/projects', 'POST', { name: 'Other project' })).body;
    const path = '/api/projects/1/tasks';
    const otherPath = `/api/projects/${other.id}/tasks`;
    assert.deepEqual(await api(path), { status: 200, body: [] });
    for (const title of ['', ' \t\n ', null, 42]) {
      assert.deepEqual(await api(path, 'POST', { title }), {
        status: 400, body: { error: 'Task title is required' },
      });
    }
    assert.deepEqual((await api(path)).body, []);
    const first = await api(path, 'POST', { title: '  First task \n' });
    const second = await api(path, 'POST', { title: '<b>Literal title</b>' });
    assert.equal(first.status, 201);
    assert.equal(second.status, 201);
    assert.equal(first.body.title, 'First task');
    assert.equal(first.body.completed, false);
    assert.equal(second.body.completed, false);
    assert.ok(second.body.id > first.body.id);
    const tasks = [first.body, second.body];
    assert.deepEqual((await api(path)).body, tasks);
    assert.deepEqual((await api(otherPath)).body, []);
    const otherTask = (await api(otherPath, 'POST', { title: 'Other task' })).body;
    assert.equal((await api(`${otherPath}/${first.body.id}`, 'PATCH', { completed: true })).status, 404);
    assert.equal((await api('/api/projects/999999/tasks')).status, 404);
    assert.equal((await api('/api/projects/999999/tasks', 'POST', { title: 'Missing project' })).status, 404);
    assert.equal((await api(`${path}/999999`, 'PATCH', { completed: true })).status, 404);
    for (const completed of [0, 1, 'true', null]) {
      assert.equal((await api(`${path}/${first.body.id}`, 'PATCH', { completed })).status, 400);
    }
    for (const [endpoint, method] of [[path, 'POST'], [`${path}/${first.body.id}`, 'PATCH']]) {
      const response = await fetch(`${server.url}${endpoint}`, { method, body: '{' });
      assert.equal(response.status, 400);
    }
    assert.deepEqual((await api(path)).body, tasks);
    const completed = await api(`${path}/${first.body.id}`, 'PATCH', { completed: true });
    assert.deepEqual(completed, { status: 200, body: { ...first.body, completed: true } });
    tasks[0] = completed.body;
    assert.deepEqual((await api(path)).body, tasks);
    assert.deepEqual((await api(otherPath)).body, [otherTask]);
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual((await api(path)).body, tasks);
    assert.deepEqual((await api(otherPath)).body, [otherTask]);
    assert.deepEqual((await api('/api/projects/1')).body, { id: 1, name: 'Existing project', archived: false, defaultPriority: 'Normal', totalCount: 2, completedCount: 1 });
    assert.equal((await fetch(`${server.url}/projects/1`)).status, 200);
    assert.deepEqual(await api(`${path}/${first.body.id}`, 'PATCH', { completed: false }), {
      status: 200, body: first.body,
    });
    const third = (await api(path, 'POST', { title: 'Third task' })).body;
    assert.equal(third.completed, false);
    assert.ok(third.id > otherTask.id);
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual((await api(path)).body, [first.body, second.body, third]);
  } finally {
    await server?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

