    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual((await api(path)).body, { ...summary, archived: true });
    assert.deepEqual((await api(`${path}/tasks`)).body, tasks);
    await api(path, 'PATCH', { archived: false });
