  const priority = ui.byId('priority-filter');
  completion.value = 'Open';
  await completion.fire('change');
  priority.value = 'Normal';
  await priority.fire('change');
  const originalRows = ui.rows('task');
  select.value = 'Low';
  await select.fire('change');
